#!/usr/bin/env python3
"""Merge user records from JSON, CSV, and Parquet sources.

Priority: source_a > source_b > source_c
"""

import json
import math
from pathlib import Path

import pandas as pd

DATA_DIR = Path("/data")
OUTPUT_PARQUET = Path("/app/merged_users.parquet")
OUTPUT_CONFLICTS = Path("/app/conflicts.json")

# Source order is also the conflict-resolution priority.
SOURCES = [
    (
        "source_a",
        {
            "user_id": "id",
            "name": "full_name",
            "email": "email",
            "created_date": "registration_date",
            "status": "status",
        },
    ),
    (
        "source_b",
        {
            "user_id": "user_id",
            "name": "name",
            "email": "email_address",
            "created_date": "created_at",
            "status": "is_active",
        },
    ),
    (
        "source_c",
        {
            "user_id": "userId",
            "name": "userName",
            "email": "email",
            "created_date": "joined",
            "status": "active",
        },
    ),
]

OUTPUT_FIELDS = ["name", "email", "created_date", "status"]


def is_null(value):
    if value is None:
        return True
    if isinstance(value, float) and math.isnan(value):
        return True
    try:
        result = pd.isna(value)
        return bool(result) if not isinstance(result, (list, tuple)) else False
    except (TypeError, ValueError):
        return False


def normalize_text(value):
    if is_null(value):
        return None
    value = str(value).strip()
    return value if value else None


def normalize_date(value):
    if is_null(value):
        return None
    parsed = pd.to_datetime(value, errors="coerce")
    if pd.isna(parsed):
        return normalize_text(value)
    return parsed.strftime("%Y-%m-%d")


def normalize_status(value):
    if is_null(value):
        return None
    if isinstance(value, bool):
        return "active" if value else "inactive"
    text = str(value).strip()
    lower = text.lower()
    if lower in {"true", "1", "yes", "y"}:
        return "active"
    if lower in {"false", "0", "no", "n"}:
        return "inactive"
    return text if text else None


def normalize_user_id(value):
    if is_null(value):
        return None
    try:
        # Accept ids such as 101, 101.0, or "101".
        return int(float(value))
    except (TypeError, ValueError):
        return normalize_text(value)


def load_source(source_name, mapping):
    """Load a source and return a dict keyed by normalized user_id."""
    if source_name == "source_a":
        frame = pd.read_json(DATA_DIR / "source_a/users.json")
    elif source_name == "source_b":
        frame = pd.read_csv(DATA_DIR / "source_b/users.csv")
    else:
        frame = pd.read_parquet(DATA_DIR / "source_c/users.parquet")

    records = {}
    for raw in frame.to_dict(orient="records"):
        mapped = {
            field: raw.get(column)
            for field, column in mapping.items()
        }
        user_id = normalize_user_id(mapped["user_id"])
        if user_id is None:
            continue

        record = {
            "name": normalize_text(mapped["name"]),
            "email": normalize_text(mapped["email"]),
            "created_date": normalize_date(mapped["created_date"]),
            "status": normalize_status(mapped["status"]),
        }

        # If a source contains duplicate ids, retain the first occurrence.
        records.setdefault(user_id, record)

    return records


def main():
    source_records = {
        source_name: load_source(source_name, mapping)
        for source_name, mapping in SOURCES
    }

    all_user_ids = sorted(
        {
            user_id
            for records in source_records.values()
            for user_id in records
        }
    )

    merged_rows = []
    conflicts = []

    for user_id in all_user_ids:
        merged = {"user_id": user_id}

        for field in OUTPUT_FIELDS:
            values_by_source = {}
            for source_name, _ in SOURCES:
                record = source_records[source_name].get(user_id)
                if record is None:
                    continue
                value = record.get(field)
                if value is not None:
                    values_by_source[source_name] = value

            # Highest-priority non-null value wins.
            selected = next(iter(values_by_source.values()), None)
            merged[field] = selected

            distinct_values = set(values_by_source.values())
            if len(distinct_values) > 1:
                conflicts.append(
                    {
                        "user_id": user_id,
                        "field": field,
                        "values": values_by_source,
                        "selected": selected,
                    }
                )

        merged_rows.append(merged)

    output_columns = ["user_id", "name", "email", "created_date", "status"]
    merged_frame = pd.DataFrame(merged_rows, columns=output_columns)
    merged_frame["user_id"] = merged_frame["user_id"].astype("int64")
    for column in ["name", "email", "created_date", "status"]:
        merged_frame[column] = merged_frame[column].astype("string")

    merged_frame.to_parquet(OUTPUT_PARQUET, index=False)

    report = {
        "total_conflicts": len(conflicts),
        "conflicts": conflicts,
    }
    with open(OUTPUT_CONFLICTS, "w", encoding="utf-8") as handle:
        json.dump(report, handle, indent=2, ensure_ascii=False)
        handle.write("\n")

    print(f"Wrote {len(merged_frame)} users to {OUTPUT_PARQUET}")
    print(f"Wrote {len(conflicts)} conflicts to {OUTPUT_CONFLICTS}")


if __name__ == "__main__":
    main()
